#include <iostream>
#include <algorithm>
using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int T;
    if (!(cin >> T)) return 0;
    while (T--) {
        long long X, Y, Z;
        cin >> X >> Y >> Z;
        if (Y >= 2 * X) {
            long long twoPacks = (Z + 1) / 2;
            cout << twoPacks * X << "\n";
        } else {
            long long fourPacks = Z / 4;
            long long rem = Z % 4;
            if (rem == 0) {
                cout << fourPacks * Y;
            } else if (rem <= 2) {
                cout << fourPacks * Y + min(X, Y);
            } else {
                cout << fourPacks * Y + min(2 * X, Y);
            }
            cout << "\n";
        }
    }
    return 0;
}
